    N<ComboBox>("CatalogCategory").ItemsSource=new[]{"全部分类"}.Concat(routeState.plans.Select(p=>PlatformCategory(p)).Distinct()).ToArray();N<ComboBox>("CatalogCategory").SelectedIndex=0;foreach(var plan in routeState.plans){var p=plan;var card=new Grid();card.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(48)});card.ColumnDefinitions.Add(new ColumnDefinition());card.Children.Add(new Border{Width=44,Height=44,CornerRadius=new CornerRadius(11),Background=Hex(p.id=="pypi"||p.id=="zenodo"?"#496CAD":"#FFFFFF"),Padding=new Thickness(4),VerticalAlignment=VerticalAlignment.Top,Child=PlatformIcon(p.id,p.mark,36)});var labels=new StackPanel{Margin=new Thickness(9,0,0,0)};var name=Text(p.name,13,true);name.Margin=new Thickness(0,0,0,4);name.MaxHeight=40;labels.Children.Add(name);var service=Text(p.service.Replace(" · 已登记下载域名",""),10);service.Margin=new Thickness(0,0,0,4);service.MaxHeight=32;service.SetResourceReference(TextBlock.ForegroundProperty,"Muted");labels.Children.Add(service);var health=Text("未检测",10);health.Margin=new Thickness(0);health.SetResourceReference(TextBlock.ForegroundProperty,"Accent");catalogHealth[p.id]=health;labels.Children.Add(health);Grid.SetColumn(labels,1);card.Children.Add(labels);var button=new Button{Content=card,Height=118,HorizontalContentAlignment=HorizontalAlignment.Stretch,Padding=new Thickness(12,14,10,10),Margin=new Thickness(0,0,10,10),ToolTip=p.name+" · "+p.note};button.Click+=(s,e)=>SelectRoute(p,"");catalogCards[p.id]=button;N<System.Windows.Controls.Primitives.UniformGrid>("RoutingCards").Children.Add(button);}SavedRoute saved=null;try{saved=json.Deserialize<SavedRoute>(File.ReadAllText(RoutePreferencePath));}catch{}var initial=routeState.plans.FirstOrDefault(p=>saved!=null&&p.id==saved.id)??routeState.plans.First();SelectRoute(initial,saved==null?"":saved.host);ShowPicker(true);
