  void FilterPlatforms(){if(routeState==null)return;string query=N<TextBox>("PlatformSearch").Text.Trim();string category=N<ComboBox>("CatalogCategory").SelectedItem as string;string nextFilter=query+"|"+category;if(nextFilter!=catalogFilter){catalogFilter=nextFilter;window.Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Loaded,new Action(()=>N<ScrollViewer>("CatalogScroll").ScrollToTop()));}int visible=0;foreach(var p in routeState.plans){Button b;if(!routeCards.TryGetValue(p.id,out b))continue;bool match=query.Length==0||(p.name+PlatformCategory(p)+String.Join(" ",p.hosts)+routeHealth[p.id].Text).IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0;b.Visibility=match?Visibility.Visible:Visibility.Collapsed;Button card;if(catalogCards.TryGetValue(p.id,out card))card.Visibility=match&&(String.IsNullOrEmpty(category)||category=="全部分类"||category==PlatformCategory(p))?Visibility.Visible:Visibility.Collapsed;if(card!=null&&card.Visibility==Visibility.Visible)visible++;}foreach(var label in categoryLabels)label.Visibility=((string[])label.Tag).Any(id=>routeCards[id].Visibility==Visibility.Visible)?Visibility.Visible:Visibility.Collapsed;N<TextBlock>("PlatformCount").Text=routeCards.Count+" 个来源 · 可搜索";N<TextBlock>("CatalogCount").Text=visible+" / "+routeCards.Count+" 个来源";}
