  void SelectRoute(RoutePlan plan,string host){routePlan=routeState==null?plan:routeState.plans.FirstOrDefault(p=>p.id==plan.id)??plan;ShowPage("routing");ShowPicker(false);N<Border>("RoutingHeroIcon").Background=Hex(routePlan.id=="pypi"||routePlan.id=="zenodo"?"#496CAD":"#FFFFFF");N<Border>("RoutingHeroIcon").Child=PlatformIcon(routePlan.id,routePlan.mark,42);N<TextBlock>("RoutingTitle").Text=routePlan.name;N<TextBlock>("RoutingService").Text=routePlan.service;N<TextBlock>("RoutingScope").Text=routePlan.note;UpdateRouteChoices(host);UpdateRoutingView();}
  void SaveRouteChoice(){var choice=N<ComboBox>("RoutingChoice").SelectedItem as RouteChoice;if(routePlan==null||choice==null)return;try{Directory.CreateDirectory(Path.GetDirectoryName(RoutePreferencePath));File.WriteAllText(RoutePreferencePath,json.Serialize(new SavedRoute{id=routePlan.id,host=choice.Host}),Encoding.UTF8);}catch(Exception e){Log("选择未能保存："+e.Message);}}
  void UpdateRoutingView(){if(routePlan==null||routeState==null)return;bool steam=routePlan.id=="steam";var choice=N<ComboBox>("RoutingChoice").SelectedItem as RouteChoice;var selectedHosts=choice!=null&&!String.IsNullOrEmpty(choice.Host)?new[]{choice.Host}:routePlan.hosts??new string[0];SetNodeHosts(selectedHosts);N<TextBlock>("RoutingDomains").Text=selectedHosts.Length>0?"接管域名："+String.Join("  ·  ",selectedHosts):"尚未发现下载域名，请先在 Steam 开始下载，再刷新下载服务器。";var active=routeState.routing!=null&&routeState.routing.active;var same=active&&routeState.routing.sourceID==routePlan.id&&routeState.routing.hosts.OrderBy(h=>h).SequenceEqual(selectedHosts.OrderBy(h=>h));var name=active?routeState.plans.FirstOrDefault(p=>p.id==routeState.routing.sourceID):null;N<TextBlock>("RoutingActive").Text=active?"当前接管："+(name==null?routeState.routing.sourceID:name.name)+" · "+routeState.routing.hosts.Length+" 个域名"+(routeState.routing.sourceID=="steam"?" · 本机 hosts":" · Clash 规则"):"尚未接管 · 选好平台后点击启动";N<Button>("StartRouting").Content=busy?"正在处理…":same?"✓ 已启用所选服务":active?"切换到此服务":"▷ 启动 IPv6 接管";N<Button>("StartRouting").IsEnabled=ready&&!busy&&!same&&selectedHosts.Length>0;N<Button>("StopRouting").IsEnabled=ready&&!busy&&active;N<ComboBox>("RoutingChoice").IsEnabled=!busy;
   N<StackPanel>("SteamControls").Visibility=steam?Visibility.Visible:Visibility.Collapsed;N<Button>("RefreshSteamServers").IsEnabled=ready&&!busy;N<Button>("RoutingDiagnostics").Content=steam?"验证 Steam 下载链路":"查看来源检测";N<Button>("RoutingDiagnostics").IsEnabled=ready&&!busy;N<TextBlock>("RoutingMethod").Text=steam?"Steam：精确下载域名 → 本机 hosts 双栈回环 → 官方 CDN IPv6。管理员权限用于修改 hosts，启用后请在 Steam 暂停 → 继续。":"通过本机已有 Clash 接管所选域名。客户端需要使用系统代理或已有 Clash 代理；未经过代理的流量不受控制。";
   if(steam){N<TextBlock>("SteamDiscovery").Text=steamState==null?"正在读取 Steam 下载服务器…":(steamState.clientFound?"已找到本机 Steam":"未找到本机 Steam 客户端")+" · "+(steamState.detectedHosts??new string[0]).Length+" 个日志下载域名\n"+(steamState.detail??"")+"\n启用并检测实际下载块后，再判断本次连接是否通过。";}
