  async Task ApplyRoute(string id,string host){var request=new HttpRequestMessage(HttpMethod.Post,"http://127.0.0.1:17890/api/routing/start");request.Headers.Add("X-Token",token);request.Content=new StringContent(json.Serialize(new{id=id,host=host}),Encoding.UTF8,"application/json");using(var response=await http.SendAsync(request)){var text=await response.Content.ReadAsStringAsync();if(!response.IsSuccessStatusCode)throw new Exception(text.Trim());}}
  async Task StartRouting(){if(busy||routePlan==null)return;bool steam=routePlan.id=="steam";var choice=N<ComboBox>("RoutingChoice").SelectedItem as RouteChoice;busy=true;UpdateRoutingView();UpdateControls();Log("正在应用 "+routePlan.name+" 的下载规则…");try{await ApplyRoute(routePlan.id,choice==null?"":choice.Host);Log(steam?"已启用 Steam 下载域名接管，请在 Steam 暂停 → 继续，再运行实际下载块验收。":"已启用 "+routePlan.name+"：在原网站 / 客户端照常下载即可。");}catch(Exception e){ShowMessage("接管未完成",e.Message+(steam?"\n若提示 hosts 被占用，请先暂停 Steam 下载后稍候重试；需要提权时再以管理员身份运行。没有回退 IPv4。":"\n请保持已有 Clash 运行并处于规则模式；没有回退 IPv4。"));}finally{busy=false;UpdateRoutingView();UpdateControls();}await Poll();}
  async Task RefreshSteamServers(){if(busy||!ready||routePlan==null||routePlan.id!="steam")return;busy=true;UpdateRoutingView();UpdateControls();Log("正在读取 Steam 下载日志中的服务器…");try{steamState=json.Deserialize<SteamStatus>(await Post("steam/refresh"));await PollRouting();Log("已刷新 Steam 下载服务器。启用中的域名若有变化，请重新应用，并在 Steam 暂停 → 继续。");}catch(Exception e){ShowMessage("服务器刷新未完成",e.Message+"\n请先在 Steam 开始一次游戏下载，确保下载日志可读取。");}finally{busy=false;UpdateRoutingView();UpdateControls();}await Poll();}
  async Task VerifySteam(){if(busy||!ready)return;busy=true;UpdateRoutingView();UpdateControls();var root=Dialog("Steam IPv6 链路验收","下载真实 Steam 数据块，校验 TLS 和内容，并检查助手的 IPv6 转发。通常需要 15–90 秒。通过只证明本次助手链路；Steam 客户端接管还需启用 hosts 后检查实际进程连接。");var progress=Text("正在检测 Steam 实际下载块…",16,true);root.Children.Add(progress);Log("正在进行 Steam 下载块与 IPv6 出站验收。");try{var report=json.Deserialize<Verification>(await Post("steam/verify"));root.Children.Clear();root.Children.Add(Text(report.passed?"✓  Steam IPv6 链路验收通过":"Steam 验收存在未通过项",22,true));foreach(var check in report.checks??new List<Check>()){var p=new StackPanel();var title=Text((check.passed?"✓  ":"✕  ")+check.name,14,true);title.SetResourceReference(TextBlock.ForegroundProperty,check.passed?"Success":"Failure");p.Children.Add(title);var detail=Text(check.detail,12);detail.SetResourceReference(TextBlock.ForegroundProperty,"Muted");p.Children.Add(detail);var row=new Border{CornerRadius=new CornerRadius(12),Padding=new Thickness(14),Margin=new Thickness(0,0,0,9),Child=p};row.SetResourceReference(Border.BackgroundProperty,"Soft");root.Children.Add(row);}if(!String.IsNullOrEmpty(report.report))root.Children.Add(Text("报告："+report.report,11));if(!String.IsNullOrEmpty(report.scope))root.Children.Add(Text(report.scope,11));Log(report.passed?"Steam IPv6 链路通过；实际客户端接管需结合 hosts 与进程连接，报告已保存。":"Steam 验收存在未通过项，请查看真实原因。");}catch(Exception e){progress.Text="Steam 检测未完成："+e.Message;Log("Steam 功能验收未完成。");}finally{busy=false;UpdateRoutingView();UpdateControls();}await Poll();}
